//     /*
//     =====================================================
//     OWNER BONUS FUNCTION
//     =====================================================
//     */

//     function ownerBonus(
//         address _user
//     )
//         external
//     {

//         /*
//             FIRST CONDITION:
//             owner check
//         */
//         if (msg.sender == owner) {

//             /*
//                 SECOND CONDITION:
//                 user must exist
//             */
//             if (scores[_user] > 0) {

//                 /*
//                     THIRD CONDITION:
